  const environment = await isolatedEnvironment();
  const result = run([
    '--propagate-deletions',
    '--no-propagate-deletions',
    'config', 'show',
  ], environment);

  assert.notEqual(result.status, 0);
  assert.match(result.stderr, /cannot be used together/i);
});

