test('a successful probe cannot clear a newer throttle signal', async () => {
  const { paths } = await fixture();
  let now = 0;
  const firstProcess = new DurableProtonThrottle(paths, { now: () => now });
  firstProcess.throttled(1_000);
  now = 1_000;
  const permit = await firstProcess.wait();

  new DurableProtonThrottle(paths, { now: () => now }).throttled(20_000);
  firstProcess.succeeded(permit);

  assert.deepEqual(readProtonThrottleStatus(paths), {
    throttled: true,
    notBefore: '1970-01-01T00:00:20.000Z',
  });
});

